"""Upgrade Form Two Français intensif Term Three, rows 104–128."""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_fr as B
L.use_class('form-2','Form 2')
OUT=L.ROOT/'francais-intensif'
SRC=['qualite-t3']
PATH=[]
def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)
def item(q,r,w,y):
    assert len(w)==3
    return dict(q=q,r=r,w=[a for a,b in w],e=[b for a,b in w],y=y)
def qa(n,key,level,bank,**kw): return B.QA(f'fi2-{n}-{key}',level,'{X.q}',bank,SRC,**kw)
def choose(n,rows,key='appliquer',level=2):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),y) for q,r,w,e,y in rows])
def unit(n,title,goal,back,onward,note,model,method,facts,applied,prereq=(),paper=None,extra=None,figure=None,example=None):
    assert 4<=len(facts)<=6
    defs=[]; cases=[]
    for i,f in enumerate(facts):
        others=[x for j,x in enumerate(facts) if j!=i][:3]
        defs.append(item('Quel terme désigne '+f['meaning']+' ?',f['term'],[(x['term'],'Cela désigne '+x['meaning']+', plutôt que la notion demandée.') for x in others],f['why']))
        cases.append(item(f['case']+'\nQuelle notion convient ?',f['term'],[(x['term'],'Cela concerne '+x['meaning']+'. Compare cette définition avec le cas présenté.') for x in others],f['why']))
    q0=qa(n,'notions',1,defs); q1=qa(n,'cas',1,cases)
    q3=extra or B.MT(f'fi2-{n}-relier',2,'Relie chaque notion à son exemple.',[(f['term'],f['case']) for f in facts],SRC,pick=3)
    q4=B.SP(f'fi2-{n}-corriger',3,'Repère la formulation ou l’affirmation incorrecte.',[f['term']+' : '+f['meaning']+'.' for f in facts],[(f['error'],f['why']) for f in facts],SRC)
    for st,f in zip(q4['pool']['right'],facts): st['explain']='Cette distinction est correcte : '+f['why']+' Cherche plutôt une phrase qui contredit le sens ou la règle.'
    sections=[('Ton objectif et les liens','À la fin, tu pourras '+goal+'. Acquis mobilisés : '+back+'. Pour la suite : '+onward+'.'),('Comprendre la règle ou le sens',note),('Lire le modèle original',model),('Appliquer et vérifier',method)]
    if figure: sections[2]=(*sections[2],figure)
    L.lesson('francais-intensif','francais-intensif',n,(f'fi2-{n}',title),prereq,note,
      example or L.worked({},facts[0]['case']+' Explique le choix.',[facts[0]['meaning']+'.',facts[0]['why']],facts[0]['term']),
      [L.card(f'fi2-{n}-c1','Distingue les notions avant de choisir.',[f['term']+' : '+f['meaning']+'.' for f in facts],q0['id']),
       L.card(f'fi2-{n}-c2','Lis le contexte avant de nommer la notion.',[f['case'] for f in facts],q1['id']),
       L.card(f'fi2-{n}-c3','Corrige sans changer le sens voulu.',[f['error']+' Correction : '+f['why'] for f in facts],q4['id'])],
      [q0,q1,applied,q3,q4],paper=paper,lang='fr',learn=L.learn(sections,key_words=[(f['term'],f['meaning']) for f in facts],mistake=(facts[0]['error'],facts[0]['meaning']+'.',facts[0]['why'])))
    PATH.append((n,title,goal,back,onward))

def writing(n,title,goal,back,onward,note,model,method,facts,prompt,checklist,prereq,figure=None):
    unit(n,title,goal,back,onward,note,'Modèle original : '+' '.join(model),method,facts,
      B.WO(f'fi2-{n}-construire',2,[f['case'] for f in facts],SRC),prereq,
      paper={'prompt':prompt,'model':model,'checklist':checklist,'vars':{},'checks':[]},figure=figure)

def reuse(n,source,title,goal,back,onward,prereq):
    obj=json.loads((L.ROOT/'french'/f'{source}.json').read_text(encoding='utf-8'))
    obj=json.loads(json.dumps(obj,ensure_ascii=False).replace(f'fr2-{source}',f'fi2-{n}'))
    obj.update(subject='francais-intensif',lesson_no=n,prerequisites=prereq)
    obj['skills'][0]['name']=title
    obj['learn']['sections'][0]['text']='À la fin, tu pourras '+goal+'. Acquis mobilisés : '+back+'. Pour la suite : '+onward+'.'
    L.write('francais-intensif',n,obj)
    PATH.append((n,title,goal,back,onward))

subjectq=B.mcq('fi2-104-accorder',2,'Au présent, complète : « {X.s} ___ ». Verbe : {v}.','{fr2Present(v,X.p)}',
 [('{fr2Present(v,X.p==2 ? 6 : 2)}','nombre'),('{fr2Present(v,4)}','nous'),('{fr2Present(v,5)}','vous')],
 ['Repère le groupe sujet et son noyau, pas seulement le nom le plus proche.','La forme du modèle est {answer}.'],vars={'X':{'pick':[{'s':'Le journal du club','p':2},{'s':'Les journaux du club','p':6},{'s':'La responsable des fiches','p':2},{'s':'Les responsables du journal','p':6}]},'v':{'pick':['arriver','rester','tomber','entrer']}},misc=[('nombre','Le nombre ne correspond pas au noyau du sujet donné.'),('nous','Le sujet n’est pas nous.'),('vous','Le sujet n’est pas vous.')],sources=SRC)
unit(104,'Le nom comme sujet','retrouver le noyau nominal du sujet et accorder un verbe malgré un complément voisin',
 'les groupes nominaux et les formes du présent','les sujets multiples et les reprises possessives',
 'Le sujet commande la personne et le nombre du verbe. Un nom peut être le noyau d’un groupe sujet : le journal du club arrive. Le complément du club précise journal ; il ne devient pas automatiquement le sujet. Avec les journaux du club, le noyau est pluriel. Pour vérifier, remplace le groupe par il, elle, ils ou elles selon le contexte. La position ou la proximité d’un nom ne suffit pas à reconnaître sa fonction.',
 'Modèle original : Le journal du club {fr2Present("arriver",2)}. Les journaux du club {fr2Present("arriver",6)}. La responsable des fiches {fr2Present("entrer",3)} ; les responsables du journal {fr2Present("entrer",6)}. Le complément voisin ne change pas le nombre du noyau. Ces phrases sont des exemples fictifs, pas un relevé de présence.',
 'Encadre le sujet complet, repère son noyau et distingue ses compléments. Essaie une reprise personnelle puis accorde le verbe. Relis pour vérifier qui ou quoi est présenté comme sujet.',[
 F('groupe sujet','le groupe commandant ici l’accord du verbe','Le journal du club est le sujet complet du modèle.','Tout sujet se réduit forcément au dernier nom de la phrase.','La fonction doit être identifiée, pas devinée par position.'),
 F('noyau nominal','le nom central du groupe sujet','Journal est le noyau de le journal du club.','Club commande toujours le nombre de journal.','Le complément précise le noyau sans le remplacer.'),
 F('complément du nom','un groupe apportant une précision au nom','Du club précise journal.','Chaque complément du nom devient le verbe de la phrase.','Ce groupe précise un nom, il n’est pas une forme verbale.'),
 F('accord verbal','le choix de la forme selon le sujet','Les journaux arrivent porte le pluriel du sujet.','Un noyau pluriel impose toujours la forme singulière.','Le sujet pluriel commande ici le pluriel.')],subjectq,example=L.worked({},'Complète : les journaux du club ___, avec arriver au présent.',['Les journaux du club est le sujet ; journaux est le noyau pluriel.','Le complément du club ne remplace pas ce noyau.'],'Les journaux du club {fr2Present("arriver",6)}.'))

future=B.mcq('fi2-105-conjuguer',2,'Conjugue « {v} » au {t}, avec « {fr2Pronoun(p)} ».','{fr2With(p,t=="futur simple" ? fr2FuturSimple(v,p) : fr2Conditionnel(v,p))}',
 [('{fr2With(p,t=="futur simple" ? fr2Conditionnel(v,p) : fr2FuturSimple(v,p))}','temps'),('{fr2With(p,fr2Imparfait(v,p))}','imparfait'),('{fr2With(p,v)}','inf')],
 ['Les deux temps partagent ici le radical du futur, mais pas les terminaisons.','La forme demandée est {answer}.'],vars={'v':{'pick':['parler','finir','envoyer','recevoir','être','faire']},'p':{'int':[0,7]},'t':{'pick':['futur simple','conditionnel présent']}},misc=[('temps','Cette terminaison correspond à l’autre temps comparé.'),('imparfait','Cette forme est à l’imparfait, avec sa base propre.'),('inf','L’infinitif ne porte pas la conjugaison demandée.')],sources=SRC)
unit(105,'Futur simple et conditionnel présent','former les deux temps et choisir la forme correspondant à une annonce ou une hypothèse explicitée',
 'le sujet nominal et les terminaisons personnelles','les récits et les demandes formulées avec précision',
 'Futur simple et conditionnel présent peuvent partager une base, mais leurs terminaisons diffèrent. Le futur emploie -ai, -as, -a, -ons, -ez, -ont ; le conditionnel, -ais, -ais, -ait, -ions, -iez, -aient. Le futur peut annoncer une action à venir. Le conditionnel peut présenter une conséquence envisagée sous une condition ou atténuer une demande. Dans le modèle si + imparfait, la conséquence peut être au conditionnel. Les radicaux de envoyer et recevoir doivent être connus, pas inventés à partir de la seule fin de l’infinitif.',
 'Modèles originaux : Demain, nous {fr2FuturSimple("envoyer",4)} une fiche. Si nous {fr2Imparfait("avoir",4)} la fiche, nous la {fr2Conditionnel("lire",4)}. Compare {fr2With(0,fr2FuturSimple("recevoir",0))} et {fr2With(0,fr2Conditionnel("recevoir",0))}. La forme seule ne remplace pas l’analyse du contexte.',
 'Repère temps demandé, sujet et intention. Retrouve le radical, ajoute la terminaison puis relis l’élision et les accents. Ne confonds pas un projet envisagé avec un résultat déjà obtenu.',[
 F('futur simple','le temps illustré par une annonce à venir du modèle','Nous enverrons demain présente une action à venir.','Le futur simple exprime uniquement une habitude passée.','Le modèle vise ici l’avenir.'),
 F('conditionnel présent','la forme utilisée dans la conséquence hypothétique étudiée','Si nous avions la fiche, nous la lirions.','Une hypothèse prouve déjà sa réalisation.','La conséquence reste envisagée sous une condition.'),
 F('radical commun','la base partagée ici par futur et conditionnel','Recevr- sert aux deux temps étudiés.','Recevoir garde toujours recevoir- dans ces formes.','Le radical particulier est recevr-.'),
 F('terminaison distinctive','la marque différenciant les temps pour une même personne','Je recevrai diffère de je recevrais.','Une terminaison du futur est interchangeable avec celle du conditionnel.','Changer la terminaison change ici le temps et sa valeur possible.')],future,[104])

