sources['qualite-t3']={'ref':'Supports, récits, paroles et dessins originaux ; OQLF et Portail linguistique du Canada pour les règles ; CNIL pour la prudence numérique générale','urls':urls,'checked':'Références officielles et passages indexés consultés le 2026-10-24. Formes variables calculées par french2.js. Réemploi explicite des modèles French Form Two 75 et 79 pour les lignes 106/119 ; objectifs, identifiants et prérequis adaptés. Aucun texte prescrit inventé ni enregistrement ; aucune procédure juridique française ou inscription à un réseau social enseignée. Terminologie, profondeur et réalisations orales à vérifier par un enseignant.'}
source_path.write_text(json.dumps(sources,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
lines=['# Français intensif — Form Two, troisième trimestre','','| Ligne | Sujet | À la fin | Acquis mobilisés | Suite |','|---|---|---|---|---|']
